WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_language_sentence_fill_ending'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '结尾句填空', 'kp-xingce-language-sentence-fill-ending', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "结尾句填空"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总结前文，升华主题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "横线在文章最后，且前面有个“因此”、“总之”之类的词。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "结尾句相当于文章的主旨句！它必须能够【笼罩全文】。如果选项只是文章中某个例子的细节，绝对不能作为总结句。"}]}]}$$ AS jsonb), NULL, '结尾句填空的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "语句表达", "结尾句填空"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_sentence_fill_ending", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
